    faq_a_bag_examples_list: "Nová taška přichází s příklady, které můžete změnit nebo smazat jako cokoli jiného: Domov (nákup, recepty, jídla na tento týden), Rodina (malé chvíle, seznam na narozeninovou oslavu, kroužky a aktivity), Nápady (nápady na víkend, nápady na dárky podle toho, jak blízký je vám daný člověk, a co s ušetřenými penězi) a Výlety (místa, kam chcete jet, co sbalit na výlet, co sbalit na hotel a seznam na let do zahraničí). Taška, která už existovala, dostane jednou ty nejnovější – do svých vlastních kapes.",
    faq_q_bag_examples_list: "Jaké příklady obsahuje Moje taška?",
    faq_a_nm_me1_guide: "Me – vaše postava v New Me, ve své první podobě (Me1). Poprvé, hned po připojení, se otevře portál ze světla obklopený jiskrami, Me z něj vyletí, pár klepnutími vysvětlí, co vás čeká, a pak zůstává u každé otázky: během výběru jídel s vámi píše do své knihy a klepnutí na radu ukáže další. Na konci Me s vámi slaví a vezme vás na krátkou prohlídku – a když prohlídka skončí, má pro vás ještě jednu malou chvilku. Když odejdete v polovině – otázek nebo prohlídky –, příště se Me zaraduje, že vás vidí, a zeptá se, jestli pokračovat od stejného místa. „Přeskočit“ nahoře úvod přeskočí.",
