    faq_a_shop_holidays: "V Nákupním Seznamu klepněte na dárek: postupně se objeví svátky vaší země (té vybrané v Nastavení) s daty – každý rok se vypočítají samy. Klepněte na svátek a otevře se hotový seznam toho, co se na něj obvykle kupuje; vše je vybrané (kromě toho, co už v seznamu máte), zrušte výběr u toho, co nepotřebujete, a klepněte na „Přidat do seznamu“. Dva týdny před svátkem se nahoře v seznamu objeví malá karta; ✕ ji skryje do dalšího svátku.",
