    shop_hol_not_now: "Teď ne",
    faq_a_shop_delivery: "V Nákupním Seznamu klepněte na náklaďák: vyberte, co je v zásilce (vše je vybrané), kdy dorazí – dnes, zítra nebo jiný den – a v jakou dobu (dopoledne, odpoledne, večer nebo „Jiné…“ pro vlastní čas). Tyto položky se přesunou na kartu „Na cestě“ nahoře v seznamu, i se dnem a časem. Když ten den nastane, v Mém Dni se objeví „Dorazila zásilka?“ (a na kartě je „Dorazila?“). Pokud dorazilo všechno, přesunou se do „Koupit znovu“. Pokud něco chybí, klepněte na to, co nedorazilo, a vrátí se to rovnou do seznamu.",
    faq_a_shop_departments: "Seznam se sám řadí podle oddělení v supermarketu – ovoce a zelenina, pečivo, mléčné výrobky a vejce, maso a ryby, trvanlivé potraviny, mražené, nápoje, pochutiny, drogerie, hygiena, pro děti a zvířata – takže procházíte uličkami popořadě. Oddělení se pozná podle názvu položky. Pokud položka skončila na špatném místě, klepněte na ni a vyberte její oddělení, nebo „Jiné…“ a napište vlastní.",
    faq_a_shop_share_qty: "Ano. Vedle každé položky + přidá jeden kus (×2, ×3…) a − jeden ubere. Tlačítko sdílení nahoře v Nákupním Seznamu pošle celý seznam, úhledně seřazený podle oddělení, přes WhatsApp, e-mailem nebo jako kopii.",
    faq_a_shop_two_buttons: "Obě znamenají „koupeno“. ✕ je pro něco, co kupujete jen jednou – zmizí ze seznamu (a čeká v archivu 🗑️ pro případ omylu). ↺ je pro věci, které kupujete pořád znovu – zmizí ze seznamu a čekají v „Koupit znovu“: otevře ho malé tlačítko ↺ vedle koše dole v seznamu a jedno klepnutí tam vrátí položku do seznamu. V „Upravit“ uvnitř z něj můžete položku odebrat. Když přidáváte položku, dříve koupené věci se objeví jako návrhy, a pokud už v seznamu je, jen se z ní stane ×2 místo druhého řádku.",
    faq_q_shop_delivery: "Jak funguje „Mám objednané doručení“?",
