    nm_demo_title: "Jak funguje výměna",
    faq_a_new_me_challenge_journal: "Když výzva skončí – velká, mini nebo výzva týdne –, v oslavě je tlačítko 📝 Jak to šlo?, které otevře stránku v deníku výzev: jak to bylo (pět obličejů), co pomohlo, co bylo těžké a co si vzít s sebou dál – nic z toho není povinné a může to počkat i na později. Deník je diamant v kouzelném batohu: každá dokončená výzva s datem a tím, co bylo napsáno, nejnovější nahoře – klepnutím na kteroukoli ji můžete číst, upravit nebo sdílet (sdílí se jen to, co je na stránce). Dokončená výzva dostane také medaili v úspěších, pod „Splněné výzvy“. Deník výzev je oddělený od běžného deníku.",
    faq_q_new_me_challenge_journal: "Co je deník výzev?",
