    nm_chj_title: "Deník výzev",
    nm_chj_write: "Napsat, jak to šlo",
    nm_swap_time: "Čas",
    faq_a_ai_reminder_in_text: "Ano – napište ho spolu s úkolem, například „zítra v 17:00 vyzvednout balík, s připomenutím hodinu předem“. Připomenutí se uloží přímo k úkolu: hodinu předem, půl hodiny, den předem a tak dále, a „připomeň mi“ bez času znamená 10 minut předem. Připomenutí napsané v textu má přednost před polem připomenutí ve stejném okně.",
    faq_q_ai_reminder_in_text: "Mohu požádat AI asistenta o připomenutí ve stejném požadavku?",
    myday_meals_all_done: "Všechna dnešní jídla jsou odškrtnutá 🍽️",
    nm_tour_week_text: "Malá výzva na týden. ✓ každý den – a na konci klíč.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "z {total}",
    books_home_off_toast: "Kniha zmizela z domovské obrazovky",
    books_home_on_toast: "Kniha je na domovské obrazovce 📖",
    books_home_pin: "Na domovské obrazovce",
    books_home_q: "Na které stránce jsem?",
    books_home_save: "Uložit",
    faq_a_books_home_chip: "Ano. V Čtenářském koutku klepněte na kartě knihy, kterou právě čtete, na 📌 Na domovské obrazovce. Pod pozdravem na domovské obrazovce se objeví malé tlačítko s knihou a stránkou – klepněte na něj, napište číslo nové stránky a uložte, a pokrok se zaznamená (i v Čtenářském koutku). Dalším klepnutím na 📌 ji odeberete. Může tam být i několik knih najednou – pro každou jedno tlačítko – a je to stejné na všech zařízeních.",
    faq_a_new_me_week_challenge: "Malá výzva na jeden týden podle vašeho výběru. V chodbě je velká karta: „Na čem chcete tento týden pracovat?“ – klepněte na ni, vyberte oblast (se sebou, s druhými, učit se a růst, klid, malé odvážné kroky, domov a rutina) a výzvu a zvolte, kdy začne. Stejné výzvy jsou i na obrazovce výzev, pod 🌱 Osobní rozvoj. Každý den odškrtnete ✓ na kartě (jeden volný den v týdnu) a každý skončený týden přinese nový klíč do tajného světa. „Číst 2 stránky denně“ se odškrtne samo ze stránek zapsaných v Čtenářském koutku. Po skončení týdne ji 📌 Ponechat jako denní úkol přidá do Mé Rutiny v čase, který zvolíte, s ✓ každý den. Najednou běží jedna výzva týdne; velké i mini výzvy pokračují vedle ní.",
    faq_a_room_genie: "Na verandě u moře klepnutí na Aladinovu lampu vyvolá lesního ducha – a začne rozhovor: jaké je vaše přání (co chcete ve svém životě změnit), jaký to bude pocit, až se splní, co je na cestě těžké a jak lze právě tuto situaci obrátit v dobré. Pak zhruba jak dlouho to potrvá, první malý krok a další dva a „když… tak…“ pro chvíle, kdy to bude těžké. Na konci se zobrazí celé přání krok za krokem a může se stát cílem v Mých Cílech (kroky se stanou etapami na cestě, s datem podle zvolené doby; tam lze všechno změnit) nebo se uložit do deníku – a pak se duch rozloučí. Nic se neuloží, pokud nevyberete jednu z těchto možností. Od druhé návštěvy se duch nejdřív zeptá, zda chcete ve svém životě změnit ještě něco: ano – stejný rozhovor; teď ne – připomínka dosáhnout cílů, které už jsou stanovené. Duch vychází jednou denně: když se přání uloží (nebo po „Teď ne“), odpočívá do zítřka. Otázky vycházejí z dobře známého způsobu, jak z přání udělat plán: přání, výsledek, překážka a plán.",
    faq_q_books_home_chip: "Mohu na domovské obrazovce vidět svou knihu a stránku?",
    faq_q_new_me_week_challenge: "Co je výzva týdne?",
