    nm_me_choose: "Vybrat",
    nm_me_on_screen: "Na obrazovce",
    faq_a_new_me_game: "V New Me zůstávají herní tlačítka vždy na stejném místě – v chodbě, v tajném pokoji i všude v lese; mění se jen obraz uprostřed. Nahoře: den na cestě, klíče, série a dnešní energie (kolik z plánu už bylo snědeno) a pod tím další mise – další jídlo i s časem (klepnutí ho otevře, s ✓ Snědeno). Po straně: celý den, výzvy a moje cesta, a vedle nich výzva týdne – jejích 7 dní a ✓ na dnešek. Dole: kouzelný batoh (celé New Me – mapa světa, moje cesta, nákupní seznam, úspěchy, deník výzev, měření, fotky, měsíční kalendář, denní tabulka, připomínky, menu v PDF a nastavení; otevře se jako samostatná obrazovka). Mapa světa, první věc v batohu, ukazuje všechna místa v lese – klepnutím na místo se tam přenesete; u zamčeného místa je vidět, kolik klíčů potřebuje. Me je vaše postava na lesní stezce: začíná jako Me1, po několika výzvách (4 klíče) vyroste v Me2 a ke konci (9 klíčů) v Me3 – s proměnou, kterou můžete sledovat. Klepnutím na Me uvidíte všechny fáze – každou už dosaženou postavu lze znovu vybrat, takže se může vrátit i dřívější. Me se vznáší – přetahuje se prstem nebo myší a vchod, kterého se dotkne, se otevře (u zamčeného je vidět, kolik klíčů chybí). Me s vámi chodí i do každého pokoje a na každé místo a vznáší se tam, kde ho necháte: přetáhněte ho kamkoli a přetažením zářícího kruhu pod ním ho otočíte úplně dokola; dívá se směrem, kterým se pohybuje (na počítači: šipky ho posouvají, Q a E ho otáčejí). V chodbě se malým 🏠 pod horní lištou vrátíte na domovskou obrazovku; v každém pokoji a na každém místě vás tlačítko ve stejném rohu vrátí do chodby.",
    faq_q_new_me_game: "Jak fungují herní tlačítka, mapa světa a Me?",
