    room_magic_song_rec3: "Zvonkohra vodopádu",
    faq_a_new_me_menu_build: "Nejdřív se dotazník zeptá, která jídla jíte a kdy (2 jídla + svačina, 2 jídla + lehká večeře, nebo obojí), a jestli je něco i večer – k jídlu nebo k pití, co a v kolik. Při volbě „2 jídla + svačina“ je to oběd (11:30) a večeře (19:00), svačina je v 16:00. Potom se zobrazí všechny možnosti pro tato jídla. U každého jídla vyberte až 2 oblíbené – v menu pak stojí „tohle nebo tamto“. U některých možností (pita a pomazánka, cereálie s mlékem, něco lehkého) vyberete až 3 věci, které vám chutnají, každou v její vlastní porci, a v menu stojí „tohle nebo tamto nebo tamto“; kalorie se řídí výběrem. Káva a nápoje fungují stejně. Každá volba je vyvážená, takže den dává přesně 1 300 nebo 1 500. Změnit to můžete kdykoli: ⚙️ Nastavení → 🍽️ Sestavte si menu, nebo „Vyberte až 3, které vám chutnají“ na kartě jídla.",
