    nm_picks_label: "Vyberte až 3, které vám chutnají",
    faq_a_myday_water_toggle: "Ano. Sklenice vody v Mém Dni (s + pro další sklenici) se zobrazuje ve výchozím nastavení. Pro skrytí vypněte „Zobrazit vodu v Mém Dni“ v Nastavení > Přizpůsobení a kalendář. Nic se nesmaže – Sledování Pitného Režimu funguje dál a po opětovném zapnutí se sklenice vrátí.",
    faq_q_myday_water_toggle: "Můžu skrýt vodu v Mém Dni?",
    myday_water_toggle_label: "Zobrazit vodu v Mém Dni",
    faq_a_routine_newme_sync: "S New Me má ⚙️ v Mé Rutině přepínač „Synchronizovat s New Me“. Když je zapnutý (výchozí), dnešní jídla New Me se zobrazují v Mém Dni i v Mé Rutině – místo jídel rutiny, která byla skryta. Když je vypnutý, jídla New Me z obou zmizí a rutina je přesně taková jako dřív. Nic se nemaže – opětovné zapnutí vše vrátí a zeptá se, která jídla v rutině skrýt.",
    faq_q_routine_newme_sync: "Jak zapnout nebo vypnout synchronizaci New Me s Mou Rutinou a Mým Dnem?",
