    theme_name_watercolor_wash: "Akvarel",
    faq_a_food_list_languages: "Vestavěný seznam potravin vznikl z izraelských jídel a jejich hebrejských názvů. Ve všech ostatních jazycích se každá potravina zobrazuje pod anglickým názvem a vyhledávání najde jakýkoli anglický název, který zná (například 'broth' najde Clear soup); potraviny, které mají jen hebrejský název, se tam nezobrazují. Cokoli, co v seznamu není, stačí napsat vlastními slovy – odhad pomocí AI funguje v každém jazyce.",
    faq_q_food_list_languages: "Proč seznam potravin v mém jazyce ukazuje anglické názvy a méně potravin?",
    settings_copyright_line: "© 2026 všechna práva vyhrazena. vývoj aplikace: eden zabari.",
    workout_ready_replace_btn: "Nahradit",
    faq_a_sport_workout_ai: "V „Moje tréninky“ → ⋯ → „Plán s AI“ (a když je tabulka prázdná, i na dlaždici vedle hotových plánů). Odpovězte pár klepnutími – kolikrát týdně, kdy, místo, úroveň a cíl, skoro všude je i „Jiné“ – a když chcete, přidejte volný řádek, třeba citlivé koleno nebo uběhnout 5 km do léta. AI sestaví celý týden: druhy tréninku, dny, časy, délku, intenzitu, cviky a dny odpočinku. Než se cokoli uloží, ukáže se náhled: „Vložit do mé tabulky“ (místo tabulky nebo navíc), „Jiný návrh“ (až 3krát) nebo „Změnit odpovědi“. Plán je schválně umírněný, a když zmíníte bolest nebo zranění, dostanete šetrné možnosti a doporučení poradit se s odborníkem. Používá stejný limit AI jako rozvrh a rutina: 5krát zdarma a 60krát měsíčně s Premium.",
