    workout_ai_when_morning: "Ráno",
    workout_ai_when_noon: "V poledne",
    workout_ai_when_ph: "např. po práci, nebo 17:30",
    workout_ai_working: "Plán se vytváří…",
    faq_a_sport_workout_jar: "Každý druh tréninku má vlastní barevnou hvězdičku – běh růžovou, chůze zelenou, plavání modrou a tak dál. Každý trénink zapsaný tento týden, z tabulky nebo zvlášť, hodí svou hvězdičku do sklenice nahoře v „Mých trénincích“ a sklenice se plní až k týdennímu cíli (klepnutím na ni cíl změníte). Po dosažení cíle sklenice zazáří. Malá sklenice vedle počítá, kolik týdnů v řadě byla plná.",
    faq_q_sport_workout_jar: "Co jsou barevné hvězdičky a sklenice v „Mých trénincích“?",
    faq_a_sport_workout_gcal: "Ano – v ⋯ → Kalendář Google (po připojení Kalendáře Google v Nastavení). Každý trénink s časem se stane událostí, která se opakuje každý týden v jeho dny, a změny v aplikaci ji aktualizují. Připomenutí chodí jen z aplikace, takže Google nepřidává vlastní, a tréninky se v aplikaci nikdy neobjeví dvakrát. Dalším klepnutím se z Kalendáře Google odeberou jen tréninky.",
    faq_q_sport_workout_gcal: "Můžou se moje tréninky zobrazovat v Kalendáři Google?",
    workout_gcal_btn: "Kalendář Google",
    workout_gcal_error: "Kalendář Google se nepodařilo aktualizovat – při další změně se to zkusí znovu",
    workout_gcal_not_connected: "Nejdřív připojte Kalendář Google v Nastavení",
    workout_gcal_off_toast: "Tréninky byly z Kalendáře Google odebrány",
    workout_gcal_on_toast: "Vaše tréninky jsou v Kalendáři Google",
    faq_a_sport_workout_reminder: "Ano – v tréninku, Připomenutí: 10 minut, 30 minut nebo hodinu předem, nebo vlastní čas (trénink musí mít čas). Zazvoní jako ostatní připomenutí, jednou a na jednom místě: v aplikaci, pokud je otevřená, jinak na telefonu. „Hotovo“ zapíše trénink do historie a „Ještě ne“ připomene znovu za 5 minut.",
    faq_q_sport_workout_reminder: "Můžu dostat připomenutí před tréninkem?",
    workout_reminder_30min: "30 minut před",
    workout_reminder_label: "Připomenutí",
    workout_reminder_need_time: "Přidejte čas, abyste dostali připomenutí",
    faq_a_sport_workout_share: "V ⋯ → Sdílet se z týdne stane skleněný obrázek v barvách vašeho motivu s nenápadným odkazem na aplikaci (na telefonu jde rovnou do nabídky sdílení, na počítači se obrázek uloží). ⋯ → PDF k tisku otevře přehlednou stránku celého týdne s políčkem k odškrtnutí u každého tréninku a cviku – zvolte „Uložit jako PDF“ nebo ji vytiskněte. Plán je také v datovém přehledu v Nastavení, v části Sport.",
    faq_q_sport_workout_share: "Jak nasdílím nebo vytisknu svůj tréninkový týden?",
    share_image_saved: "Obrázek je uložený – můžete ho přiložit",
    share_save_image: "Uložit obrázek",
    workout_pdf_btn: "PDF k tisku",
    workout_share_btn: "Sdílet",
    faq_a_sport_workout_board: "V ⋯ → Týdenní tabule je každý den sloupec: přetáhněte trénink na jiný den (na telefonu nejdřív podržte). V tréninku „Také v Mé Rutině“ ho vloží do rutiny v jeho čase a dnech a změny se synchronizují oběma směry; z položky v Mé Rutině udělá „Přidat do mých tréninků“ opak. ✓ na jednom místě se počítá na obou a v Mém Dni se trénink objeví jen jednou – ve štítku vedle vody.",
    faq_q_sport_workout_board: "Jak přesunu trénink na jiný den a propojím ho s Mou Rutinou?",
    routine_in_workouts_btn: "Otevřít v mých trénincích",
    routine_to_workout_btn: "Přidat do mých tréninků",
    routine_to_workout_done: "Přidáno do mých tréninků 💪",
    workout_delete_confirm_routine: "Zmizí z plánu i z Mé Rutiny. Tréninky už zapsané v historii zůstanou.",
    workout_moved: "Přesunuto na: {day}",
    workout_routine_need_time: "Přidejte čas, aby šel dát do Mé Rutiny",
    workout_routine_toggle: "Také v Mé Rutině",
    workout_view_board: "Týdenní tabule",
    workout_view_timeline: "Časová osa",
    faq_a_sport_workout_plan: "V Sledování Tréninku, v části „Moje tréninky“: + Trénink – druh, dny, čas, délka, intenzita a místo (i „Jiné“). Posilovací, funkční a plavecké tréninky můžou mít seznam cviků a „Odpočinek“ označuje den odpočinku. Můžete začít i z hotového plánu. Dnešní trénink je vidět velký a pod ním celý týden; ✓ ho zapíše do historie tréninků i s intenzitou. V ⋯ se nastavuje týdenní cíl (tréninky nebo minuty) – každý odcvičený trénink hodí svou hvězdičku do sklenice.",
    faq_a_sport_workout_today: "V Mém Dni vedle vody ukazuje malý štítek dnešní trénink – klepnutí otevře podrobnosti, ✓ a ▶. ▶ spustí stopky, které běží dál i ve štítku na úvodní obrazovce, a „Dokončit“ zapíše trénink se skutečným časem. Pokud v New Me běží výzva „Dva týdny pohybu“, zapsaný trénink se v ní započítá sám.",
    faq_q_sport_workout_plan: "Jak si naplánuji tréninkový týden?",
