    dictation_service_off: "Diktování je v tomto prohlížeči nebo počítači vypnuté – zapněte ho v nastavení počítače, nebo zkuste Chrome",
    faq_a_new_me_magic_themes: "Pět třpytivých motivů, které jsou součástí New Me: Kouzelný les, Hvězdný prach, Růžová víla, Kouzelná polární záře a Zlatý soumrak. Vyberte jeden v New Me (⚙️ Nastavení > Barvy) nebo v Nastavení > Vzhled a zobrazení a třpytivý štětec jím obrazovku přemaluje. Kouzelný motiv přidá třpytky do celé aplikace i ke každému klepnutí. Kdykoli se můžete vrátit k jakémukoli jinému motivu.",
