    apptour_focus_text: "Všechno ustoupí stranou kromě jedné věci na teď – s velkým ✓. Pak se objeví další.",
    apptour_m_presets_text: "Vaše uložená jídla na jednom místě: hledání, nedávno použitá, podle denní doby – a ＋ přidá jedno na dnešek.",
    apptour_night_text: "🌙 ztmaví celou aplikaci, ☀️ vrátí den.",
    apptour_noteline_text: "Napište a klepněte na ➤ – uloží se do poznámek. 📝 na začátku přepne na 🛒 nákupy nebo 🍎 uložené jídlo.",
    apptour_search_text: "Poznámky, nákupy, kalendář, recepty, sešity, cíle, tabulky a knihy – jedno hledání najde všechno.",
    faq_a_new_me_ai_menu: "Před menu se dotazník ptá, která jídla jíte a kdy (2 jídla + svačina, 2 jídla + lehká večeře, nebo obojí), jestli večer jíte něco malého a v kolik, co nejíte a jak pijete kávu nebo čaj. Potom AI sestaví 3 možnosti pro každé jídlo – každou velkou podle podílu toho jídla na dni, takže den dál dává přesně 1 300 nebo 1 500 – a nápady na nápoje, které se uloží jako vaše stálé nápoje. Vyberte až 2 oblíbené na jídlo; možnosti z původního menu jsou hned pod nimi a v 🔄 Výměně přicházejí po vašem osobním menu. 🔄 Jiné možnosti sestaví novou sadu (3krát na dotazník). Chcete-li změnit odpovědi nebo kdykoli sestavit nové menu: ⚙️ Nastavení → ✨ Osobní menu (AI).",
    faq_q_new_me_ai_menu: "Jak funguje osobní menu v New Me?",
