    apptour_start: "Začít prohlídku",
    nm_sales_premium: "Zahrnuje celé Premium",
    nm_unlock_premium: "A celé Premium je odemčené taky.",
    settings_sub_status_newme: "Premium je součástí tvého New Me.",
    room_back_to_shelf: "K polici",
    faq_a_new_me_day_total: "Každý den vyjde přesně na plán: jídla, asi 150 kalorií na kávu a nápoje během dne a to, co bylo vybráno na večer – něco malého k jídlu nebo něco k pití. Na večer vyberte až 3, které vám chutnají (například banán, jogurt nebo 2 čtverečky hořké čokolády; nebo bylinkový čaj, čaj s trochou mléka nebo teplé mléko), a jejich kalorie se odečtou z jídel. Každá volba se vyrovná sama: menší nebo větší možnost, vynechané jídlo, malá snídaně a malé jídlo, které k ní patří, nebo večer – rozdíl se přidá k jídlům nebo se od nich odečte, ke každému podle jeho velikosti, a pod každým jídlem je napsáno kolik (+ nebo −) a co přidat nebo vynechat. Jídlo, které už je odškrtnuté, zůstane tak, jak bylo zapsáno. V dotazníku je u každého jídla vidět jeho úprava a malý rámeček ukazuje jídla, nápoje, večer a součet. Máte ten den chuť na něco jiného? Hlavně ať celkový součet kalorií zůstane stejný nebo nižší.",
    faq_q_new_me_day_total: "Jak den v New Me vyjde přesně na 1 300 / 1 500 a kam se počítají nápoje?",
