    nm_swap_balanced: "{n} kalorií rozdělených mezi jídla, aby den vyšel na {plan}",
    books_quotes_chip: "Citáty",
    faq_a_book_quotes: "Na polici v tajném pokoji (Citáty) nebo přes malý štítek 💬 Citáty v Čtenářském koutku – je to tentýž seznam. Klepni na „+ Citát“, napiš větu a vyber knihu z Čtenářského koutku, nebo napiš jiný název přes „✏️ Ostatní“; autor je nepovinný. ✏️ citát upraví a 🗑️ ho smaže. Citáty jsou záložky, mezi kterými se posouvá – 🎨 nahoře přepne na fotky nebo zeď kartiček.",
    faq_a_room_wish_jar: "Na polici v tajném pokoji stojí skleněná sklenice na sny. Klepněte na malou sklenici na horní polici (nebo Police > Sklenice přání) a napište, jak chcete, aby váš život vypadal – odvážně, bez správně a špatně. Každé přání se přeloží do lístečku a spadne do sklenice. „Vytáhnout lísteček“ otevře náhodný a každý lísteček jde otevřít i samostatně. Od druhého otevření stejného přání z něj můžete udělat cíl a rozdělit ho na malé kroky. Jednou týdně se jemně objeví lísteček s jedním z vašich přání – bez tlaku, jen připomínka, kam míříte.",
    faq_q_book_quotes: "Kam si ukládat citáty z oblíbených knih?",
    faq_q_room_wish_jar: "Co je sklenice přání v tajném pokoji?",
