    faq_a_saved_meals_page: "Uložená jídla mají vlastní stránku: Výživa a Metriky > ⭐ Uložená jídla (nebo ⭐ v nabídce). Hledání nahoře najde jídlo podle názvu nebo suroviny, „Nedávno použitá“ ukazují, co jste přidali v poslední době, a karty (Snídaně, Oběd, Večeře, Polévky…) ukazují každou denní dobu. „+ Dnes“ přidá jídlo do dnešního Denního Sledovače Jídel, na další volné místo. Klepnutím na jídlo ho upravíte nebo smažete a ＋ nahoře přidá nové.",
