    presets_tab_sweet: "Sladkosti",
    faq_a_notes_sticky_look: "Poznámky jsou krátký seznam skleněných karet – 🎨 nahoře v Poznámkách mění vzhled celých Poznámek: seznamu, tlačítek dnů nahoře i okna, ve kterém se poznámka píše – sklo, čistý seznam, kartičky nebo washi páska. Přetahovaná poznámka si ponechá přesně svůj vlastní vzhled a barvu. Klepnutím na text poznámky ji otevřete – tam ji můžete upravit, změnit barvy a vidět, kdy byla naposledy napsaná. Až bude hotovo, klepněte na ○ a × ji přesune do archivu (🗑️ dole v seznamu ji vrátí). Přetažením za ⠿ změníte pořadí, přesunete ji pod „Později“ nebo na den nahoře. ! označí poznámku jako naléhavou – jemně vyplave do prvních řádků s malým štítkem „Naléhavé“; dalším klepnutím se označení zruší.",
    faq_q_notes_sticky_look: "Jak poznámku otevřu, upravím nebo odstraním?",
    note_to_archive_btn: "Přesunout do archivu",
    faq_a_routine_clash: "Pokud je v tu dobu ve stejné dny už nějaká položka, objeví se dvě možnosti: „Nahradit“ – nová položka dostane tento čas a pro tu původní vyberete jiný (při úpravě existující položky se nabídne její předchozí čas, takže se obě prostě prohodí), nebo „Obojí“ – obě zůstanou ve stejný čas, jedna pod druhou. Pokud jsou dny různé (například jedna Ne–Čt a druhá v pátek), nic se neptá.",
    faq_q_routine_clash: "Co se stane, když dám položku do rutiny na čas, který už je obsazený?",
    routine_clash_both: "✌️ Obojí – obě v {time}",
    routine_clash_move_btn: "Přesunout a uložit",
    routine_clash_move_to: "Na kolik hodin přesunout „{title}“?",
    routine_clash_replace: "🔄 Nahradit – a přesunout „{title}“ na jiný čas",
    routine_clash_title: "V {time} už je: {title}",
    faq_a_new_me_coffee: "Pod dnešním jídelníčkem je krátké shrnutí: kolik kalorií mají dohromady všechna dnešní jídla, kolik zbývá na kávu a nápoje, a tlačítka pro vybranou kávu a nápoje – jedním klepnutím se přidá do Nápojů. V „Vyberte až 3, které vám chutnají“ pod tlačítky (a v dotazníku) si vyberete, co se zobrazí: voda / sodovka, bylinkový čaj, light limonáda, černá / americano (~5), čaj s trochou mléka (~25), káva na vodě s mlékem nebo rostlinným nápojem do 100 ml (~50), lehké kakao, teplé mléko nebo obyčejná káva / latte (~120).",
    faq_q_new_me_coffee: "Kde přidám kávu a jak zjistím, kolik mi zbývá na den?",
