    faq_a_recipe_examples: "Pod vašimi recepty jsou ukázkové recepty: snídaně, saláty, polévky, hlavní jídla, přílohy, svačiny, dezerty a veganská jídla, každý s dobou přípravy, kaloriemi na porci a tím, kolik gramů váží jedna porce. Klepnutím recept otevřete a „Uložit do Mých Receptů“ vytvoří vaši vlastní kopii, kterou můžete upravovat. Štítky kategorií filtrují a další klepnutí na stejný štítek zase ukáže vše.",
    faq_a_recipe_grams: "V receptu je vedle kalorií napsáno „1 porce ≈ X g“. U vlastních receptů vyplňte ve formuláři receptu „Gramů na porci“ (a když chcete, i dobu přípravy): obojí je nepovinné a čas se ukazuje na barevném pruhu receptu.",
