    recipes_examples_title: "Ukázkové recepty",
    faq_a_recipe_scan_multi: "Ano. V „Přidat Recept“ klepněte na 📷 a vyberte jednu fotku nebo víc (nejvýš 6; funguje i PDF). Každá se objeví v krátkém seznamu, kde vyberete, co na ní je: Vše, Suroviny nebo Postup, a „➕ Další fotka“ přidá další. Pak klepněte na „✨ Naskenovat recept“: AI vše spojí do jednoho receptu, ve správném pořadí a bez opakovaných řádků, a počítá se to jako jedno skenování. Více fotek vybraných v 📷 Fotka v asistentovi AI se otevře také tady.",
    faq_q_recipe_scan_multi: "Jde naskenovat jeden recept z několika fotek, třeba suroviny a postup zvlášť, nebo dvě stránky?",
