    faq_a_note_written_at: "Klepněte na text poznámky a otevře se. Uvnitř, pod textem, je vidět, kdy byla naposledy napsaná, s přesným datem a časem. Aktualizuje se jen při změně samotného textu: archivace a obnovení, zaškrtnutí ✓, barvy ani přesunutí poznámky to nemění.",
    faq_q_note_written_at: "Jak zjistím, kdy byla poznámka napsaná?",
    note_written_at: "Naposledy napsáno: {date}",
    faq_a_new_me_month: "V kouzelném batohu → Měsíční kalendář: každý den má barvu podle toho, kolik jídel bylo odškrtnuto, šipky ‹ › přepínají měsíce a pod kalendářem je denní průměr kalorií za měsíc. Klepnutí na den ukáže, kolik jídel bylo odškrtnuto a kolik kalorií se ten den snědlo.",
    faq_q_new_me_month: "Kde v New Me uvidím měsíc zpětně a průměrné kalorie?",
    nm_month_avg: "Průměr za měsíc: {kcal} kalorií denně · dny se záznamem: {n}",
    nm_month_day_empty: "V tento den se nic nezapsalo.",
    nm_month_day_line: "Odškrtnutá jídla: {checks} · kalorie: {kcal}",
    nm_extra_line_small: "{n} kalorií pro toto jídlo, z malé snídaně – třeba {ideas}",
    faq_a_new_me_small_breakfast: "Lehká snídaně (asi 170 kcal): špaldová pita (do 100 kcal) s pomazánkou nebo sýrem a se zeleninou – vyberte až 3, které vám chutnají, například 1 lžičku čokoládové pomazánky, 1 lžičku arašídového másla nebo plátek tvrdého sýra (do 22 %). Protože je malá, přichází s ní v jiný čas „A k tomu malé jídlo“ (o hodinu a půl později, například 11:30 → 13:00 – lze zvolit i jakýkoli jiný čas): další pita s pomazánkou, proteinový jogurt s ovocem, rýžové chlebíčky s tvarohem, cereálie s mlékem nebo půlka pity s vejci – asi do 200 kcal, s vlastním ✓. Co ještě zbude, rozdělí se mezi ostatní jídla a každé jídlo ukazuje, kolik mu přibylo, takže součet dne zůstává podle plánu. Můžete ji vybrat v dotazníku, nebo na ni přepnout jen pro dnešek přes 🔄 – třeba když se snídá pozdě.",
    faq_q_new_me_small_breakfast: "Co je „malá snídaně“ v menu New Me?",
