    faq_a_ai_icon: "Ano – v Nastavení > Vzhled a zobrazení. Výchozí je jemná bublina a s Premium můžete vybrat i vznášející se mozek nebo robota.",
    faq_a_new_me_favorites: "Ano. V dotazníku (i při jeho opakování z nastavení) můžete u každého jídla vybrat až 2 možnosti. První je v menu a pod ní je řádek „nebo“ s druhou – klepnutím na něj se jen pro dnešek přepnete na ni. A pokud se snídaně nesnědla včas, „⏰ Později“ ji přesune na pozdější část dne, aniž by se změnily kalorie.",
    faq_a_theme_mode: "Některé speciální motivy vypadají nejlépe v tmavém režimu – Akvarel, Polární záře, Barbie a dva třpytivé motivy –, takže výběr jednoho z nich přepne aplikaci do tmavého režimu a výběr jakéhokoli jiného motivu (i rakety) do světlého. Černý a Tmavě šedý zůstávají tmavé. Potom to můžete kdykoli změnit přes 🌙 v nabídce nebo Světlý Režim v nastavení.",
    faq_a_water_month: "Ve sledování vody. U každého záznamu v dnešním záznamu je čas, kdy byl přidán, a „Měsíční tabulka“ otevře celý měsíc: u každého dne je vidět, kolik litrů se vypilo (✓, když se splnil denní cíl), a klepnutí na den ukáže jeho záznamy i s časy.",
