    dev_sim_panel_title: "PM – jen pro vás",
    faq_a_new_me_weight_optional: "Ne. Aktuální i cílová hmotnost v dotazníku jsou nepovinné. Pokud se později přidá vážení (⚖️ Hmotnost v „Mé cestě“ v New Me nebo v záznamu hmotnosti), pokrok se počítá od prvního.",
    faq_q_new_me_weight_optional: "Musím v New Me zadat svou hmotnost?",
    nm_unlock_desc: "Jídelníček, výzvy i cesta jsou připravené – krok za krokem, společně.",
    nm_unlock_title: "New Me odemčeno!",
    room_reveal_star: "V dalekohledu na střeše se rozsvítila nová hvězda ✨",
    faq_a_room_records: "Gramofon stojí v pokoji od začátku, na pařezu u křesla. Jeho desky otevírají na YouTube oficiální klipy velkých hitů posledních let a pod nimi je pět klidných melodií, které hrají přímo tady v pokoji – deska se točí, dokud hrají, a „⏹ Zastavit“ hudbu vypne.",
    faq_a_room_roof_gifts: "Přicházejí s 8. klíčem. Klepnutí na dalekohled vám umožní podívat se jím: noční nebe zblízka – tažením (nebo šipkami) se můžete rozhlížet – a vaše dokončené výzvy v něm tvoří souhvězdí, jedna hvězda za každou výzvu; klepnutí na hvězdu ukáže, která to byla. Klepnutí na malou truhlu ji otevře – zatím je prázdná – a další klepnutí ji zavře.",
    faq_q_room_records: "Co je na gramofonu v tajném pokoji?",
