    faq_a_new_me_preview: "Ano. Stránka New Me začíná krátkým videem o tom, co se děje uvnitř: dotazník, lampy v chodbě, batoh, výzvy a klíče. Pod ním je vše, co obsahuje, náhled jednoho dne a krátké odpovědi.",
