    nm_trailer_replay: "Přehrát znovu",
    ai_chat_food_edit: "✏️ Opravit kalorie / bílkoviny",
    ai_chat_food_invalid: "Kalorie musí být číslo větší než 0",
    ai_chat_food_updated: "Aktualizováno:",
    faq_a_ai_chat_food_fix: "Ano. Pod odpovědí v chatu klepněte na ✏️ Opravit kalorie / bílkoviny, změňte čísla a klepněte na Uložit. Změní se jen to, co se právě přidalo – i když se to připojilo ke svačině, která už tam byla. AI se může mýlit, proto se vyplatí to rychle zkontrolovat.",
    faq_a_new_me_home_btn: "S New Me otevře malý 💎 vedle režimu soustředění, nahoře na domovské obrazovce, dnešní menu. Dnešní jídla jsou vidět i v Mém Dni, každé s ✓.",
    faq_a_routine_item_days: "Ano. Klepněte na položku v Moje Rutina a vyberte její dny v 📅 Dny – například jen pondělí až pátek. V ostatní dny se v Můj Den neukazuje a nemá ✓; v Moje Rutina zůstává, bledší, s dny vedle sebe. Karta, která se po 3 dnech bez ✓ ptá na položku, počítá jen dny té položky.",
    faq_q_ai_chat_food_fix: "Dají se opravit kalorie nebo bílkoviny poté, co asistent zapíše jídlo?",
    faq_q_new_me_home_btn: "Kde je New Me na domovské obrazovce?",
    faq_q_routine_item_days: "Může být jedna položka v Moje Rutina jen v některé dny?",
    routine_item_days_label: "📅 Dny",
    home_note_meal_ph: "Najít uložené jídlo…",
    menu_quick_search: "Rychlé hledání",
    nm_times_hint: "Tip: můžete nastavit nejpozdější čas, kdy obvykle jíte každé jídlo – třeba 9:00, pokud často jíte kolem 8.",
    room_game_marquee: "Cestou – zastavit se a užít si",
    room_sand_erase_aria: "Promnutím smažete nápis",
    faq_a_home_note_line: "Napište ji do řádku uprostřed domovské obrazovky a klepněte na ➤ (nebo Enter) – uloží se do Poznámek. Klepnutím na 📝 na začátku řádku se změní na 🛒: pak to, co napíšete, půjde do Nákupního Seznamu. Dalším klepnutím na 🍎: napište pár písmen, objeví se odpovídající uložená jídla a jedním klepnutím jídlo zapíšete do dnešních jídel. S 🎤 to můžete prostě říct.",
    faq_a_night_mode: "Otevřete nabídku ☰ a klepněte nahoře na 🌙 – celá aplikace ztmavne. ☀️ na stejném místě vrátí den. Najdete to i v Nastavení, u Světlého Režimu.",
    faq_q_home_note_line: "Jak napíšu rychlou poznámku z domovské obrazovky?",
    faq_q_night_mode: "Jak přepnu do nočního režimu?",
    menu_day_mode: "Denní režim",
    menu_night_mode: "Noční režim",
    faq_a_secret_room_yoga: "Na konci lesní stezky stojí zářící brána a za ní, u vodopádu, sedí lesní bytosti – Lumi, Puffi, Nixie a Sparklet – na svých podložkách v půlkruhu a Flora, učitelka jógy, sedí čelem k nim na jediné podložce na kameni. Klepněte na Floru: otevře oči, všechno se přiblíží a rozhovor začne pomalu, s časem na čtení – Flora se ptá, jak se všichni mají, každá bytost odpoví pod svým jménem (u každého řádku je malý obrázek toho, kdo právě mluví) a pak se zeptá vás, jak se cítíte s blízkými lidmi. Rozhovor pokračuje podle vašich odpovědí – dobří lidé, někdo, s kým je to těžké, nebo trochu samoty. Každá cesta končí malou misí (může jít rovnou do Mého Dne; když je úkolem něco napsat, je tu místo na psaní a text se uloží do kouzelného deníku) a pozicí se třemi společnými nádechy. ↩ vrací o krok zpět a ✦ začíná nový rozhovor. Další klíč otevře vodopád: když si sednete na kámen, všechno zmizí a zůstane jen zvuk vody. Když se nakloníte nad jezírko, z vody vystoupí otázka – co by dnes udělalo vaše skutečné já? – a odpověď se stane malým úkolem v Mém Dni. Je to laskavá chvíle, ne náhrada rozhovoru s odborníkem.",
    faq_q_secret_room_yoga: "Co se děje na józe v lese?",
