    room_waterfall_rock_aria: "Sednout si na skálu",
    room_yoga_guide_aria: "Promluvit si s Florou",
    yg_g_alone: "Děkuji za sdílení. Občas se to stává každému.",
    yg_g_alone_q: "Co by bylo příjemné, třeba jen trochu?",
    yg_g_critic: "Kritika umí bodat dlouho. Mluví o jedné chvíli – ne o celém člověku.",
    yg_g_end: "Děkuji za tuto chvíli v kruhu. Vraťte se, kdykoli budete chtít.",
    yg_g_gate: "Je dovoleno postavit hranici. Hranice není zeď – je to branka.",
    yg_g_good: "To je krásné 💛 Kdo vám tento týden udělal radost?",
    yg_g_good_msg: "Dobrým lidem stojí za to to říct. Malé děkuji jim může udělat celý den.",
    yg_g_hard: "Děkuji, že to říkáte. Co tíží nejvíc?",
    yg_g_listen: "Když vás nikdo neslyší, je to vyčerpávající. Váš hlas je důležitý, i když je tichý.",
    yg_g_new: "Noví lidé začínají malým ahoj. Kurz, procházka, skupina – jeden krok.",
    yg_g_old: "Někdo, kdo vás už zná, je teplé místo. Stačí krátká zpráva.",
    yg_g_start: "A teď vy 🌿 Jak se poslední dobou cítíte s blízkými lidmi?",
    yg_g_used: "Když dáváme a nic nedostáváme, něco uvnitř se unaví. Je v pořádku si toho všimnout.",
