    nm_time_hour: "Hodina",
    nm_time_minutes: "Minuty",
    routine_time_taken: "V tento čas už něco je: {title}",
    faq_a_new_me_times: "V dotazníku na začátku a kdykoli v nastavení New Me → „Časy jídel“. Pokud vaše rutina už časy jídel má, vezmou se odtamtud – a jídla rutiny lze skrýt a místo nich zobrazit jídla New Me. Pokud ne, vyberete, kolik jídel denně (2 jídla + svačina / 2 jídla + lehká večeře / 2 jídla + svačina + lehká večeře) a kdy které. Při volbě „2 jídla + svačina“ je to oběd v 11:30, svačina v 16:00 a večeře v 19:00 (každý čas lze změnit). To jsou vaše časy jídel všude: v chodbě, v Mém Dni, v Mé Rutině i v připomínkách. Ať zvolíte cokoli, kalorie dne zůstanou stejné – co se vynechá, rozdělí se mezi ostatní jídla.",
    faq_q_new_me_times: "Jak nastavím časy jídel v New Me?",
    nm_times_count: "Kolik jídel denně?",
    nm_times_from_routine: "Ano, vzít je z mé rutiny",
    nm_times_hide: "Skrýt jídla z mé rutiny a místo nich zobrazit jídla New Me",
