    nm_times_manual: "Ne, vybrat tady",
    nm_times_none_found: "V rutině zatím nejsou žádná jídla – vyberte tady, kolik a kdy.",
    nm_times_q: "Má vaše rutina pevné časy na jídlo?",
    nm_times_saved: "Časy jídel uloženy",
    nm_times_title: "Časy jídel",
    faq_a_routine_exact_time: "Ano. Když AI popíšeš rutinu s přesným časem (třeba „16:10 trading“), uloží se přesně tak – bez zaokrouhlení na celou hodinu. Všechno, co je v rutině zapsané, se na tabuli zobrazí vždy, i když ta hodina není vybraná v nastavení hodin, a odebrání hodiny, ve které něco je, se nejdřív zeptá. Čas jde změnit i ručně: klepni na čas v okně položky a vyber hodinu a minuty.",
    faq_q_routine_exact_time: "Může mít moje rutina přesný čas, třeba 16:10?",
