    room_vinyl_stop: "⏹ Zastavit",
    routine_hour_remove_text: "Co je zapsané v tento čas, se z rutiny smaže: {title}",
    routine_hour_remove_title: "Odebrat {time}?",
    faq_a_routine_ai: "V Moje Rutina otevřete ⚙️ (nebo ➕) a klepněte na „Nová rutina s AI“: popište rutinu jednoduchými slovy – například „vstávání v 7, posilovna v 8, práce do 17“ – a AI vytvoří novou kartu s časy a činnostmi. Pokud text uvádí dny („ve všední dny“), karta se otevírá v těchto dnech a různé rutiny pro různé dny se stanou samostatnými kartami. Potom jde všechno upravovat jako obvykle.",
    faq_a_routine_daysoff: "V Moje Rutina klepněte na ➕ a pak na „Volné dny“: vyberte dny (například sobotu a neděli) a jaká je v nich rutina – bez plánu (zůstane volno), vlastní rutina, nebo řekněte AI, co děláte, a ona ji sestaví. Volné dny dostanou vlastní kartu a v těchto dnech Moje Rutina a Můj Den ukazují jen ji.",
    faq_q_routine_ai: "Jak vytvořím rutinu s AI?",
