    routine_daysoff_pick_days: "Vyberte aspoň jeden den",
    routine_daysoff_what: "A jaká je v těch dnech rutina?",
    routine_daysoff_which: "Které dny?",
    faq_a_secret_room_diary: "Jen vy. Stránky deníku se ukládají do účtu, takže jsou na každém zařízení a nikdo jiný je nevidí. Otevře ho kouzelný deník na psacím stole v tajném pokoji a také deník v hudebním koutku. Pod novou stránkou je složená měsíční tabulka: tečka označuje každý den, ve kterém je stránka, a klepnutí na den otevře jeho stránky – tam se dá stránka i smazat. Když je deník už otevřený, dá se přidat i do hlavní nabídky – přepínačem přímo v deníku nebo v nastavení New Me.",
    faq_a_secret_room_places: "Každý vchod u lesní brány se otvírá vlastním klíčem. Za nimi: veranda u moře (na stolku Aladinova lampa – stačí klepnout a vystoupí z ní lesní duch v kouzelné mlze, zatočí se kolem a zahájí rozhovor o vašem přání – viz „Co dělá duch lampy?“), kytara a deník (kytara hraje krátkou klidnou melodii a sama utichne, a každá ze tří desek zavěšených na stromě hraje svou vlastní kouzelnou melodii – dalším klepnutím ji zastavíte – a do deníku na pařezu se píše), místnost pro dýchání (tiché jezero při západu slunce – na vodě plave lotosový lampion: klepněte na něj, napište přání a on s ním odpluje daleko zpět do jezera; kouzelnou hůlkou můžete do písku napsat, co chcete pustit, a zůstane to tam, dokud to nesmažete prstem) a lesní stezka (otevírá se v noci a klepnutí na lucerny ji přepne na den; z velké větve visí kouzelná houpačka, na lavičce se dá sedět a klepnutí na ceduli ji přiblíží – tabule se šesti malými otázkami k odškrtnutí). Na zamčeném vchodu je vidět, kolik klíčů ještě chybí. Na konci stezky vede zářící brána k józe u vodopádu – a odtud k samotnému vodopádu.",
