    dev_weather_preview_label: "Náhled – jen na vašem účtu:",
    faq_a_ai_chat: "Klepnutím na bublinu se otevře chat. Vyberte, co chcete udělat – něco do kalendáře, zapsat jídlo, fotku receptu nebo novou tabulku – nebo prostě pište a asistent pochopí, o co jde. U kalendáře lze zvolit jednou, každý týden nebo každý den. Odpověď přijde do chatu a odtud lze pokračovat k něčemu dalšímu nebo otevřít kalendář / zapsané jídlo.",
    faq_a_new_me_hall: "New Me začíná u brány kouzelného lesa a každý vchod v něm je místo: kulaté dveře v obřím stromě vedou do tajného pokoje, dutý kmen na verandu u moře, houbový domek ke kytaře a deníku, malý vrbový oblouk do místnosti pro dýchání, velký vrbový oblouk na lesní stezku a květinový oblouk se žebříkem vede nahoru na hvězdnou střechu, jakmile se střecha otevře. Na zamčeném vchodu visí zámek. Na stezce se vznáší vaše postava Me a všude kolem jsou herní tlačítka: další mise, výzva týdne, kouzelný batoh s celým New Me, mapa světa a nástroje. Klepnutí na klíče nahoře vysvětlí, jak se klíče získávají.",
    faq_a_new_me_routine_meals: "Když jsou v New Me nastavená jídla a Moje Rutina má také jídla, New Me se zeptá, zda je skrýt a místo nich zobrazit jídla New Me – aby se nic nezobrazovalo dvakrát. Moje Rutina pak ukazuje jídla New Me v jejich časech, s 💎 a ✓ (klepnutí na název jídla otevře okno pro výběr jiného jídla nebo změnu jeho času, přímo tam nad rutinou). Nic se nemaže: vrátí se přes ⚙️ Nastavení v New Me → Jídla v rutině, nebo vypnutím „Synchronizovat s New Me“ v ⚙️ v Mé Rutině. Bez aktivního New Me se vrátí automaticky.",
    faq_a_room_computer: "Je to malý chat, který začíná otázkou „Jak zatím probíhá váš den?“ – dobře, hekticky nebo těžce – a pokračuje s vámi krok za krokem až k jedné malé misi na konci (která může jít i rovnou do Mého Dne). Odpovědi lze klepnout nebo napsat volně – napsaný text se přiřadí k nejbližší odpovědi. „↩ Zpět“ vrátí o krok, aby šlo odpovědět jinak, a „Nový chat“ kdykoli začne znovu. Po hektickém nebo těžkém dni je možné se k počítači vrátit později týž den: „Jsem zpátky...“ v rozhovoru pokračuje. Zelené světlo dole počítač vypíná a zapíná. Ukládají se jen volby, jen v tomto zařízení a jen do konce dne.",
    faq_q_ai_chat: "Jak mluvit s asistentem?",
    faq_q_new_me_hall: "Co je chodba v New Me?",
    faq_q_new_me_routine_meals: "Proč Moje Rutina zobrazuje jídla New Me?",
    faq_q_room_computer: "Jak funguje počítač v tajném pokoji?",
