    dictation_mic_denied: "Mikrofon je zablokovaný – povolte ho přes 🔒 vedle adresy v prohlížeči nebo v nastavení telefonu",
    faq_a_dictation: "Ano – klepněte na mikrofon 🎤 v rohu rychlé poznámky nebo stránky na psaní v sešitě a mluvte: slova se píšou během mluvení, v jazyce aplikace. Dalším klepnutím zastavíte. Poprvé prohlížeč požádá o povolení mikrofonu. Funguje v Chrome / Androidu a v Safari na iPhonu. Na počítači potřebujete mikrofon a prohlížeč jako Chrome, Edge nebo Safari – když něco chybí, zpráva přesně řekne co.",
    faq_q_dictation: "Můžu mluvit místo psaní?",
    faq_a_secret_room: "Pokoj jen pro vás, uvnitř New Me – dům v nitru obřího stromu. Vidíte vždy jednu stěnu a otáčíte se šipkami (nebo přejetím). První klíč přijde po ✓ u jídla ve 3 různých dnech a otevře dveře – a s nimi celý pokoj: počítač, hru, gramofon, polici s knihovnou uvnitř a kočku. Potom každá dokončená výzva (i výzva týdne) dá klíč, který otevře další místo: hvězdnou střechu, verandu u moře, kytaru a deník, místnost pro dýchání, lesní stezku s jógou, vodopád a překvapení na střeše – a 8. přinese láhev z moře s dopisem z minulosti uvnitř. Když se něco otevře, šipka ukáže cestu k němu. Malá dvířka ve spodní části herního automatu se také otevřou – skříňka za nimi je zatím prázdná. Na hvězdné střeše padá hvězda, na kterou klepnete, jako padající hvězda, a kočka sedí na polštáři.",
