    home_streak_title: "Dny v řadě s alespoň jedním ✓",
    settings_good_things_label: "„3 dobré věci“ večer",
    settings_weather_hint: "Déšť, mraky nebo sníh v pozadí domovské obrazovky podle počasí tam, kde jste. Přibližná poloha zůstává v tomto zařízení a ověřuje se přes náš server u MET Norway.",
    settings_weather_label: "Počasí na obloze domovské obrazovky",
    weather_failed: "Počasí se teď nepodařilo zjistit.",
    weather_location_denied: "Chybí přístup k poloze – povolte ho v nastavení prohlížeče a zkuste to znovu.",
    faq_a_home_focus: "Klepněte na ◎ nahoře na domovské obrazovce: zmizí vše kromě jediné věci pro teď – toho, co je v tuto hodinu, nebo další věci z dnešního seznamu – s velkým ✓ a Rychlou Poznámkou. Po ✓ se objeví další věc. Klepnutím na „Režim soustředění ✕“ nahoře se vše vrátí.",
    faq_a_home_search: "Otevřete nabídku ☰ – vyhledávání je úplně nahoře. Napište aspoň 2 písmena: výsledky přicházejí z vašich poznámek, nákupního seznamu, kalendáře, receptů, sešitů (názvy a text stránek), cílů, tabulek a knih, seskupené podle druhu – klepnutím na výsledek se k němu rovnou dostanete.",
    faq_a_my_day: "Můj Den spojuje to, co dřív bylo Pohledem na Dnešek a Mojí Rutinou, na jedné časové ose. Dole na domovské obrazovce vidíte, kolik je hotovo, co je teď nebo další (s rychlým ✓) a vedle nadpisu sklenici vody přes +1. Klepněte na ni (nebo přejeďte nahoru) a otevře se celý den: nahoře to, co nemá čas, pak vše podle hodin – úkoly, události a schůzky z kalendáře, pevné týdenní časy, dnešní rutina, malé kroky vašich cílů a jídla New Me – s čárou pro teď. Filtrujte podle Úkolů, Rutiny nebo Schůzek a událostí. ✓ tady je stejné ✓ jako všude jinde (Moje Rutina, Moje Cíle, kalendář) a rozvine sedmikrásku v koutku. „Upravit rutinu“ otevře Moji Rutinu (je i v menu) a „＋ Přidat na dnešek“ přidá úkol na dnešek. Klepnutí na nadpis „Můj Den“ (nebo na proužek nahoře) ho zase zavře.",
