    faq_a_table_shopping_link: "Ve sloupci ✓ propojeném s nákupním seznamem (jako „Suroviny doma“ v „Jídla na tento týden“) má každý dosud nezaškrtnutý řádek 🛒. Jedno klepnutí ho přidá do nákupního seznamu – jen jednou, nikdy dvakrát. Zaškrtněte ho tady ✓ a ze seznamu zmizí; smažte ho ze seznamu a tady už se neukazuje jako „v seznamu“; označte ho v seznamu jako koupený a řádek tady dostane ✓ sám. Každý sloupec ✓ lze propojit nebo odpojit v nastavení sloupce.",
