    premium_benefit_goal_library: "Celá knihovna cílů – všechny hotové plány",
    vision_goal_delete_routine_note: "Jeho položky v Mé Rutině se také smažou.",
    faq_a_goal_small_steps: "Každý cíl v sekci Moje Cíle je cesta: etapy, které už jsou za vámi, dnešní zářící kámen a pohár na konci. Dejte cíli malý krok – na každý den nebo každý týden ve zvolený den – něco, co jde i v těžký den, třeba „10 minut volného běhu“. Všechny dnešní malé kroky se zobrazují nahoře v sekci Moje Cíle a v sekci Můj Den, každý s rychlým ✓, a „✓ Dnes hotovo“ pod cestou cíle vyplní jeho tečky za posledních 7 dní. Lístek „Na cestě k 10 · nezastavujeme“ zůstává nahoře schválně: nemusíme být dokonalí – stačí každý den udělat kousek, abychom šli dopředu.",
