    faq_a_new_me_advanced: "Pokročilý režim se otevře s dárkem, po všech 20 výzvách, a dá se zapnout nebo vypnout v 🎁 Váš dárek. Dává New Me zlatý vzhled, volné sestavení menu – každá výměna ukazuje všechny možnosti bez limitu kalorií – a obrazovku 📊 Rozšířené statistiky: kalorie za posledních 30 dní v porovnání s plánem, dobré dny podle dne v týdnu, trend váhy s odhadem, kdy bude cíle dosaženo, průměry večerního check-inu a historii výzev.",
