    nm_gift_intro: "Všech {n} výzev, krok za krokem. Tohle čekalo:",
    nm_gift_title: "Váš dárek",
    faq_a_new_me_letter_gift: "Na začátku New Me (nebo později ve Výzvách) lze napsat dopis sobě do budoucna. Po zapečetění ho nejde číst ani upravit, dokud se neotevře: v láhvi z moře v tajném pokoji, nebo na konci všech 20 výzev – kde čeká i dárek.",
    faq_q_new_me_letter_gift: "Co je dopis z minulosti?",
    faq_a_new_me_challenges: "🏆 Výzvy obsahují 20 výzev: 10 velkých (třeba 5 dní bez cukru, týden bez sacharidů nebo zhubnout 4 kg za měsíc – každý den kalorický deficit, trénink a bez cukru) a 10 mini – malé návyky na týden, jako skořicová káva bez cukru. Při výběru výzvy přijde otázka, kdy začít: dnes, zítra, příští týden nebo jiný den. Jedna velká a jedna mini výzva mohou běžet současně. Probíhající výzva je nahoře v menu a v sekci Můj Den, s ✓ na daný den. Každý týden výzvy přináší jeden volný den (🍕), který ji nepřeruší, a neodškrtnutý den se počítá jako volný – odškrtnout jde dnešek i včerejšek. Některé dny se odškrtnou samy: 20minutový trénink ve Sledování Tréninku nebo jídla z menu s ✓. Každá výzva má ⓘ s tím, co přesně se počítá (například celý seznam sacharidů) – přímo ve výzvě i vedle ní v sekci Můj Den. Pod nimi je v 🌱 Osobním rozvoji 48 malých výzev na jeden týden (nepočítají se do těch 20) – viz „Co je výzva týdne?“.",
    faq_q_new_me_challenges: "Jak fungují výzvy v New Me?",
