    nm_letter_sealed_toast: "Zapečetěno ✉️ – uvidíme se v cíli",
    nm_letter_seal_note: "Po zapečetění nejde dopis číst ani upravovat, dokud nejsou všechny výzvy dokončené.",
    nm_letter_seal: "✉️ Zapečetit dopis",
    nm_letter_ph: "Kde jsem dnes, kam se chci dostat, co mi v jídle dělá potíže, co si chci říct v cíli…",
    nm_letter_intro: "Píše se teď a zapečetí se – otevře se až po všech {n} výzvách, aby bylo vidět, kolik se od té doby změnilo. Kde jsem teď? Jaké mám cíle a co mi v jídle dělá potíže?",
