    nm_ch_completed_label: "dokončených výzev",
    nm_tile_challenges: "Výzvy",
    faq_a_workout_calories: "Ano. Každý trénink dostane odhad spálených kalorií – podle typu, délky a vaší poslední hmotnosti (u běhu a kola i podle rychlosti, když je zadaná vzdálenost). Zobrazí se v seznamu tréninků a v měsíčním přehledu (Spáleno) a přičte se k rozpočtu kalorií toho dne: v Denním Sledovači Jídel, v Metrikách kalorií a hmotnosti a v kruhu New Me. Je to odhad, proto má znak ~.",
    faq_q_workout_calories: "Počítají se tréninky do denních kalorií?",
    faq_a_new_me_flexible_menu: "Ano. V dotazníku a v nastavení se volí, kolik jídel denně – 2 jídla + svačina / 2 jídla + lehká večeře / 2 jídla + svačina + lehká večeře – a ➖ na kartě jídla ho odebere (zůstanou nejméně 3); „➕ Vrátit“ ho vrátí. V každém případě kalorie dne zůstanou stejné: co se vynechá, rozdělí se mezi ostatní jídla, a pod každým jídlem je napsáno, kolik mu přibylo a co se k němu hodí. ✏️ Upravit u jídla otevře jeho text – změňte, co chcete (např. bez chleba nebo s vejcem navíc), a AI znovu spočítá kalorie a bílkoviny. 🔄 Vyměnit nabízí možnosti z jídelníčku, ⭐ Uložená a ✨ Napsat; každá změna může platit jen pro dnešek nebo odteď. A na konci „Celý den“ je ➕ Přidat jídlo – napište, co se snědlo mimo jídelníček, a AI to spočítá a přidá k dnešku (✕ smaže).",
    faq_q_new_me_flexible_menu: "Můžu v New Me změnit počet jídel nebo sníst vlastní jídlo?",
