    vision_step_schedule_weekly_hint: "Vrací se každý týden ve stejný den, dokud ho jednou neodškrtnete.",
    vision_step_schedule_weekly_label: "🔁 Každý týden až do splnění",
    vision_step_schedule_date_label: "Datum",
    vision_step_schedule_text: "Ve zvolený den se to zobrazí v sekci Můj Den a v kalendáři – ✓ tam to odškrtne i tady.",
