    vision_tagline: "Velké cíle, malé kroky.",
    faq_a_app_tour: "Prohlídka se otevře automaticky jednou, při prvním vstupu. Začíná svými částmi – klepnutím na jednu přejdete rovnou k ní – a pak ukáže všechny části aplikace (domovskou obrazovku, asistenta AI a každou položku nabídky) a pět skupin Nastavení, každou s krátkým vysvětlením, a nahlédne i dovnitř některých z nich (například ukázková cesta k cíli, taška a Google Calendar). Pokračovat posouvá dál, Zpět vrací zpět, Přeskočit tuto část přejde na další část a ✕ prohlídku zavře. Kdykoli si ji můžete pustit znovu v Nastavení > Nápověda a používání > Prohlídka aplikace a pokračovat od místa přerušení. Pokračovat a Zpět jsou vždy na stejném místě dole na obrazovce a na počítači fungují i šipky na klávesnici.",
