    table_select_option_delete_title: "Smazat možnost",
    faq_a_other_manual_option: "Všude, kde se vybírá ze seznamu možností, je také '✏️ Ostatní' - stačí ji vybrat a napsat přesně to, co je potřeba. V tabulce se sloupcem výběru (například 'Příbuzenství' v tabulce dárků) klepněte na buňku, zvolte '✏️ Ostatní', napište hodnotu (například 'Synovec') a klepněte na Přidat - uloží se jako nová možnost tohoto sloupce, takže příště už bude v seznamu. Malý × vedle každé možnosti v tomto seznamu možnost ze sloupce smaže. Při výběru ikony tabulky je k dispozici mnoho ikon (včetně barevných lepicích lístečků). Stejně to funguje u kategorií uložených jídel, kategorií receptů, kategorií opakujících se výdajů (uloží se jako nová osobní kategorie) a kategorií cílů v sekci Moje Cíle.",
