    faq_a_vision_board_today: "V sekci Moje Cíle pod cestou cíle (v „Plánu“) klepněte na 📅 vedle etapy a vyberte datum. Můžete také zapnout „🔁 Každý týden až do splnění“ – etapa se pak bude vracet každý týden ve stejný den, dokud ji jednou neodškrtnete. Ve zvolený den se etapa objeví v sekci Můj Den a v kalendáři (a také v Google Calendar, pokud je propojený) a tlačítko ukazuje, na kdy je naplánovaná. Odškrtnutí ✓ na jednom místě ji odškrtne i na druhém a posune cestu cíle dopředu. Opětovným klepnutím na 📅 změníte datum nebo etapu z kalendáře odeberete. Smazáním jednorázového úkolu z kalendáře se smaže i etapa z cíle; smazáním jednoho týdne týdenní připomínky se odebere jen tento týden.",
