    nm_drinks_hint: "Stačí napsat nápoj – kalorie se spočítají automaticky a číslo lze změnit.",
    nm_slot_drinks: "Nápoje",
    faq_a_new_me_tracking: "Klepněte na další misi nahoře v New Me a pak na ✓ Snědeno, čímž se další jídlo označí jako snědené – celé menu s ✓ u každého jídla je v části Celý den, po straně, a dnešní jídla se zobrazují také v Mém Dni na domovské obrazovce – klepnutí na některé z nich tam (nebo najetí na ně myší) ukáže přesně, co jíst, s ✓ a Vyměnit. Vše se synchronizuje s Denním Sledovačem Jídel: jídla z plánu, nápoje i cokoli přidaného jinde (např. káva z rychlého přidání) se počítají dohromady v New Me i v Mém Dni – nic už napsaného se nepřepíše a odebrání ✓ odebere jen část New Me. Když jsou všechna dnešní jídla odškrtnutá, přijde malá oslava. V části „Nápoje“ se zapisují nápoje dne – dohromady do ~150 kcal, tedy zhruba 3 nápoje po ~50 kcal. Stačí napsat název nápoje a kalorie se doplní automaticky pomocí AI. Dva řádky pro kávu/čaj mají také pole „Mléko? Kolik?“ (např. „trochu“ nebo „50 ml“) a výpočet se aktualizuje; číslo lze změnit před přidáním i po něm. Nápoj s názvem a kaloriemi se uloží automaticky, jakmile se přejde dál – klepnout na Přidat není nutné. Klepnutím na ☆ vedle nápoje se nápoj uloží jako oblíbený – oblíbené nápoje se zobrazují jako tlačítka nahoře na kartě Nápoje a jedno klepnutí je přidá ke dni. ⭐ uloží jídlo jako uložené jídlo. „Denní tabulka“ ukazuje snědená jídla s kaloriemi a bílkovinami. Malý 💎 vedle režimu soustředění, nahoře na domovské obrazovce, ho otevře přímo. Hodnoty kalorií a bílkovin jsou odhady AI a mohou obsahovat chyby. Zbylo něco z jídla? Pod odškrtnutým jídlem „Zbylo něco z jídla?“ odečte čtvrtinu, polovinu nebo tři čtvrtiny porce – nebo to, co napíšete, s výpočtem – a kalorie dne se aktualizují.",
    faq_q_new_me_tracking: "Jak v New Me fungují ✓, výměny a kalorie?",
    faq_a_new_me_what: "New Me je samostatný program denního menu se dvěma hotovými plány – 1 300 nebo 1 500 kalorií – ze 2 hlavních jídel a 2 svačin, s 3 možnostmi pro každé. Zahrnuje celé Premium. Cena: $11.99 měsíčně (zrušíte kdykoli) nebo jednorázově $99.99 doživotně. Otevírá se přes 💎 New Me v menu. Před začátkem je krátký dotazník, který začíná lékařským upozorněním, jež je třeba přijmout. Program je pouze obecná informace a nenahrazuje lékaře ani klinického dietologa.",
    faq_q_new_me_what: "Co je New Me a jak ho získám?",
