    food_estimate_local_db_reasoning: "Nalezeno v naší databázi potravin, nejde o odhad AI. Pokud to není zamýšlená položka, klepněte na „Není to správně“.",
    food_clarify_milk_question: "Je {ingredient} náhrada mléka přimíchaná do nápoje, nebo samostatná porce pevného jídla? Uveďte prosím i množství.",
