    auth_password_placeholder_login: "Heslo",
    routine_overview_no_checks: "Tento měsíc zatím nic odškrtnuto - klepněte na ✓ vedle položek své rutiny ve dnech, kdy je plníte.",
    faq_a_finance_cycle_day: "Ve výchozím stavu se přehled rozpočtu obnovuje 1. dne každého kalendářního měsíce. Pokud dostáváte výplatu jiný den (třeba 10.), nastavte zde místo toho tento den - měsíční přehled, historie i cílový rozpočet pak poběží od tohoto dne do stejného dne následujícího měsíce, místo od 1. do konce měsíce.",
    faq_q_finance_cycle_day: "Co dělá nastavení 'Den obnovení měsíčního rozpočtu'?",
    faq_a_quick_note_view_full_lists: "V nabídce ☰ jsou hned Poznámky a Nákupní Seznam. V okně Rychlé Poznámky (v Režimu soustředění) vás tam dovedou i malé 📝 a 🛒 vedle Přidat a 🍎 rychle zapíše jedno z vašich uložených jídel.",
    faq_q_quick_note_view_full_lists: "Jak z Rychlé Poznámky zobrazím celé Poznámky nebo celý Nákupní seznam?",
    note_triage_otherdate: "Jiné Datum", note_triage_otherdate_modal_title: "Vyberte datum", note_triage_otherdate_missing: "Vyberte prosím datum", note_triage_success_otherdate: "Přidáno do vašeho plánu!", notes_ai_placeholder_shopping: "Přidat do seznamu",
    daily_greeting_morning: "Dobré ráno!", daily_greeting_afternoon: "Dobré odpoledne!", daily_greeting_evening: "Dobrý večer!", daily_greeting_night: "Dobrou noc!", calorie_monthly_view_title: "Měsíční přehled", calorie_monthly_avg_label: "Denní průměr:", calorie_monthly_avg_empty: "Tento měsíc zatím nejsou zaznamenána žádná data", calorie_monthly_day_total_label: "Celkem za den:", notes_ai_added_shopping: "Přidáno do vašeho nákupního seznamu", quick_note_dest_notes: "📝 Poznámky", quick_note_dest_shopping: "🛒 Nákupní seznam",
    faq_q_calorie_monthly_view: "Jak vidím historii kalorií za celý měsíc?", faq_a_calorie_monthly_view: "Kalorické metriky mají kartu 'Měsíční přehled' s kalendářem - každý den, kdy jste zaznamenali jídlo, dostane tečku, a nad mřížkou se zobrazuje denní průměr za daný měsíc. Klepnutím na den zobrazíte přesně, co jste snědli, a celkový součet. Stejný přehled je zahrnut i při stažení osobní zprávy (PDF) z Nastavení, pokud je zaškrtnutá sekce Kalorické metriky.",
    faq_q_calorie_stats_total_vs_average: "Jsou týdenní/měsíční čísla v Kalorických metrikách součet, nebo průměr?", faq_a_calorie_stats_total_vs_average: "Obojí - velké číslo je součet (celkem) všeho zaznamenaného v aktuálním kalendářním týdnu/měsíci, a malý řádek pod ním je denní průměr. Průměr se počítá jen z dnů, kdy jste skutečně něco zaznamenali, ne ze 7 nebo z celého měsíce - den bez jakéhokoli záznamu se prostě přeskočí, nepočítá se jako 0 a nesnižuje průměr.",
    faq_q_weight_note: "Mohu přidat poznámku k záznamu váhy?", faq_a_weight_note: "Ano - vedle polí váhy/data v Pravidelném Sledování Váhy (najdete ho dole v sekci Výživa a Metriky > Metriky kalorií a hmotnosti, pod ⚖️) je volitelné pole pro poznámku. Použijte ho pro kontext, například \"po tréninku\" nebo \"ranní vážení\" - zobrazí se vedle daného záznamu v seznamu historie.",
    faq_q_quick_note_shopping_list: "Může Rychlá Poznámka přidávat rovnou do nákupního seznamu?", faq_a_quick_note_shopping_list: "Ano – v řádku pro psaní uprostřed domovské obrazovky klepněte na 📝 na jeho začátku: změní se na 🛒 a to, co napíšete, půjde rovnou do Nákupního Seznamu, mimo Poznámky.",
