    daily_focus_c1_d0: "Chránit svůj klidný prostor před hlukem kolem sebe", daily_focus_c1_d1: "Stanovovat jasné hranice - s láskou a bez pocitu viny", daily_focus_c1_d2: "Držet se svého středu, i když kolem zuří bouře", daily_focus_c1_d3: "Dávat svému klidu a energii nejvyšší prioritu", daily_focus_c1_d4: "Nepřebírat pocity a nálady druhých lidí", daily_focus_c1_d5: "Nedovolit, aby slova druhých otřásla mou hodnotou",
    daily_focus_c2_d0: "Naslouchat tomu, co potřebuje mé tělo a mysl", daily_focus_c2_d1: "Užívat si malé věci po cestě", daily_focus_c2_d2: "Zpomalit a opravdu se naladit na sebe", daily_focus_c2_d3: "Dopřát si prostor k nadechnutí uprostřed shonu", daily_focus_c2_d4: "Cítit se doma a v klidu se sebou", daily_focus_c2_d5: "Soustředit se na to, co se děje teď, bez spěchu dopředu",
    daily_focus_c3_d0: "Udržovat svá slova povzbudivá, trpělivá a chápavá", daily_focus_c3_d1: "Nebrat si nic osobně", daily_focus_c3_d2: "Nic nepředpokládat - prostě se zeptat, nebo to nechat být", daily_focus_c3_d3: "Důvěřovat vlastnímu tempu a vlastní cestě", daily_focus_c3_d4: "Pustit dokonalost a zvolit pokrok", daily_focus_c3_d5: "Mít trpělivost se svým vlastním procesem",
