    daily_focus_p6_d2_s1: "Investovat svou energii do vítězného uzavírání projektů", daily_focus_p6_d2_s2: "Jednat s jistotou toho, kdo už prokázal své schopnosti", daily_focus_p6_d2_s3: "Sdílet úspěchy a děkovat lidem, kteří byli součástí této cesty", daily_focus_p6_d2_s4: "Sklízet plody vytrvalosti a vložené tvrdé práce", daily_focus_p6_d2_s5: "Vážit si změny a růstu, které provázely cestu od samého začátku",
    daily_focus_p6_d3_s1: "Stát pevně a hrdě před vším, co se podařilo vybudovat", daily_focus_p6_d3_s2: "Prožívat chvíle plné přítomnosti v okamžicích úspěchu", daily_focus_p6_d3_s3: "Šířit kolem sebe inspiraci, štědrost a dobrou energii", daily_focus_p6_d3_s4: "Uzavírat všechny otevřené kruhy až do konce", daily_focus_p6_d3_s5: "Uznávat každou naučenou lekci a proměňovat ji v hodnotu na celý život",
    daily_focus_p6_d4_s1: "Zachovávat vnitřní klid toho, kdo dosáhl cíle", daily_focus_p6_d4_s2: "Zhluboka dýchat a užívat si plody vlastní investice", daily_focus_p6_d4_s3: "Důvěřovat si před každou novou kapitolou, která se má otevřít", daily_focus_p6_d4_s4: "Uzavírat velké kroky s elegancí a plným klidem", daily_focus_p6_d4_s5: "Děkovat za odolnost, disciplínu a sílu objevené v sobě",
    daily_focus_p6_d5_s1: "Udržovat vysoký standard jako trvalý způsob života", daily_focus_p6_d5_s2: "Zaměřovat pohled na nové vrcholy, které čekají", daily_focus_p6_d5_s3: "Volit nadšení před dalším stupněm vlastního rozvoje", daily_focus_p6_d5_s4: "Oslavovat naplnění cílů s pocitem nekonečných možností", daily_focus_p6_d5_s5: "Důvěřovat si a své schopnosti dobýt jakýkoli cíl na světě",
    daily_focus_p6_d6_s1: "S úctou dělat prostor pro osobní oslavu a zasloužený odpočinek", daily_focus_p6_d6_s2: "Shrnovat celý rok s vděčností, silou a hlubokým uspokojením", daily_focus_p6_d6_s3: "Dívat se dopředu se zvědavostí, důvěrou a láskou k cestě", daily_focus_p6_d6_s4: "Pouštět vše v hlubokém klidu s vědomím, že bylo dáno vše", daily_focus_p6_d6_s5: "Naplňovat se novou, svěží energií pro další cyklus",
    daily_focus_p6_d7_s1: "Věnovat den oslavě života, tichu a hluboké vděčnosti", daily_focus_p6_d7_s2: "Naslouchat vnitřnímu tichu z pocitu celistvosti a plného uspokojení", daily_focus_p6_d7_s3: "Ocenit v sobě celý rok růstu, odvahy a úspěchu", daily_focus_p6_d7_s4: "Pouštět vše a užívat si čistou, klidnou přítomnost", daily_focus_p6_d7_s5: "Děkovat za člověka, kterým se na této cestě stalo",
    faq_q_daily_focus_prompt: "Co je ta malá připomínka, která se ptá, co je pro mě dnes nejdůležitější udělat?", faq_a_daily_focus_prompt: "Je to prémiová denní připomínka: jednou denně se na ikoně AI asistenta objeví malý odznak „1“. Klepnutím na odznak otevřete bublinu s otázkou, co je pro vás dnes nejdůležitější udělat, a v ní se hned zobrazí 5 připravených návrhů (mění se každý den a střídají se v nich témata na celý rok, aby zůstaly svěží) a také 'Jiné' pro vlastní text - můžete vybrat víc než jeden. Klepněte na Přidat a vaše volby se zobrazí jako malé připomínkové štítky v horní části 'Můj Den' (nejsou to úkoly k odškrtnutí). Když ji zavřete pomocí ✕ nebo klepnete mimo ni, odznak jen zbledne na zbytek dne, místo aby zmizel. Ve výchozím stavu je zapnutá, ale můžete ji vypnout v Nastavení > Přizpůsobení a kalendář. Dnes to nesedí? Klepněte na „🌙 Dnes ne“ – odznak zmizí do zítřka a pak se otázka vrátí jako obvykle. Jeden z návrhů pochází z vašeho života – další krok cíle měsíce nebo dnešní čtení. Každý den začíná nanovo.",
