    auth_forgot_password_link: "Zapomněli jste heslo?", auth_back_to_login: "Zpět na přihlášení", auth_forgot_subtitle: "Zadejte svůj e-mail a my vám pošleme odkaz na obnovení:", auth_forgot_submit_btn: "Odeslat odkaz na obnovení", auth_fill_email: "Zadejte prosím svůj e-mail", auth_forgot_success: "Pokud tento e-mail existuje, odkaz na obnovení je na cestě - zkontrolujte svou schránku.",
